overlays.className:
{cn(
          "absolute right-0 top-0 h-full w-[92vw] max-w-[420px] transform transition-transform",
          isOpen ? "translate-x-0" : "translate-x-full"
        )}

overlays.label:
{
        isInAntiSnipeWindow 
          ? `Anti-snipe active! Timer extended to ${format(remaining)}` 
          : `High bid: $${highBid}${highBidder ? ` by Team ${highBidder}` : ''}`
      }

overlays.trigger:
{
                    <Button size="sm" variant="secondary" className="draft-header-control-button" title="Draft controls">
                      Controls
                      <ChevronDown size={13} aria-hidden="true" />
                    </Button>
                  }
